-- Player's Handbook II source-backed rules catalog.
-- Supplemental teamwork, affiliation, action, retraining, and rebuilding systems are represented as optional rules unless they define a generally adopted action type.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('phb2-3.5','players-handbook-ii-3-5','Player''s Handbook II','PHB2','Wizards of the Coast','dnd','3.5',
        'D&D 3.5 supplement with new classes, feats, spells, teamwork rules, affiliations, and character-revision systems.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,summary,tags,mechanics) AS (VALUES
  ('phb2-swift-action','Swift Actions','5','combat','rule',0,1,'A swift action takes very little time, can be taken whenever a free action is normally allowed, and is limited to one per turn; quickened spells and powers use this action type.','["actions","swift","combat"]','{"max_per_turn":1,"timing":"when free action is allowed","quickened_spell_or_power":true}'),
  ('phb2-immediate-action','Immediate Actions','5','combat','rule',0,1,'An immediate action can be taken even when it is not your turn. On your turn it uses that turn''s swift action; out of turn it consumes the next turn''s swift action, and it cannot be used while flat-footed.','["actions","immediate","swift","combat"]','{"usable_out_of_turn":true,"on_turn_counts_as_swift":true,"out_of_turn_consumes_next_swift":true,"usable_while_flat_footed":false}'),
  ('phb2-teamwork-benefits','Teamwork Benefits','157-158','characters','subsystem',1,0,'A trained team can qualify for shared teamwork benefits when its task leader and every required member meet the listed prerequisites and the team maintains the required roster and training.','["teamwork","party","variant"]','{"minimum_team_members":2,"maximum_team_members":8,"task_leader_min_intelligence":8}'),
  ('phb2-teamwork-benefit-progression','Teamwork Benefit Progression','158','characters','rule',1,0,'A team gains one teamwork benefit for every 4 Hit Dice of its lowest-level member and can swap a known benefit when it gains a new one if the team qualifies for the replacement.','["teamwork","progression","variant"]','{"hit_dice_per_benefit":4,"uses_lowest_member_hd":true,"swap_on_gain":true}'),
  ('phb2-team-roster','Team Roster and Membership','158','characters','rule',1,0,'A team has two to eight members. Members normally need Intelligence 3 or higher; Intelligence 1-2 creatures can participate after learning the teamwork trick, while creatures without Intelligence cannot join.','["teamwork","roster","variant"]','{"min_members":2,"max_members":8,"normal_min_intelligence":3,"animal_teamwork_trick_intelligence":[1,2],"mindless_allowed":false}'),
  ('phb2-teamwork-training','Teamwork Training','158','characters','rule',1,0,'A team trains together for at least two weeks before gaining teamwork benefits, maintains them with at least four one-week training periods each year, and a new member trains with the team for at least two weeks.','["teamwork","training","variant"]','{"initial_training_weeks":2,"maintenance_training_periods_per_year":4,"maintenance_period_weeks":1,"new_member_training_weeks":2}'),
  ('phb2-teamwork-communication','Teamwork Communication Requirement','158','characters','rule',1,0,'Unless a benefit says otherwise, teamwork benefits function when team members can communicate with one another verbally, through gestures, or by magical means.','["teamwork","communication","variant"]','{"communication_required":true,"methods":["verbal","gestures","magical"]}'),
  ('phb2-affiliations','Affiliations','163-165','campaign','subsystem',1,0,'Affiliations model social or racial organizations through membership criteria, an affiliation score, titles, duties, and benefits that change as a character''s standing rises or falls.','["affiliations","organizations","variant"]','{"categories":["social","racial"],"separate_score_per_affiliation":true}'),
  ('phb2-multiple-affiliations','Multiple Affiliations','165','campaign','rule',1,0,'A character can belong to multiple affiliations, but each additional affiliation makes all affiliation scores harder to maintain; only one set of affiliation benefits can normally be active at a time.','["affiliations","organizations","variant"]','{"primary_other_score_penalty":-10,"additional_affiliation_penalty_step":-5,"active_benefit_sets":1}'),
  ('phb2-retraining','Retraining','192','characters','subsystem',1,0,'Retraining is small-scale character revision performed when a new level is gained, replacing one earlier legal choice with another legal choice of the same general kind.','["retraining","character-revision","variant"]','{"trigger":"gain a new level","choices_per_level":1,"before_new_level_benefits":true}'),
  ('phb2-class-feature-retraining','Class Feature Retraining','192-193','characters','procedure',1,0,'When a class feature offered a choice, retraining can exchange that option for another option that could legally have been chosen at the same point, without making later choices illegal.','["retraining","class-features","variant"]','{"replacement_must_have_been_legal_at_original_level":true,"cannot_invalidate_later_choices":true}'),
  ('phb2-feat-retraining','Feat Retraining','193','characters','procedure',1,0,'A previously selected feat can be exchanged for another feat. The new feat''s prerequisites must be met both now and at the level when the old feat was originally selected.','["retraining","feats","variant"]','{"must_meet_prerequisites_now":true,"must_meet_prerequisites_at_original_level":true}'),
  ('phb2-language-retraining','Language Retraining','194','characters','procedure',1,0,'Retraining can remove one known language and replace it with another language, regardless of whether the original language came from race, Intelligence, or skill points.','["retraining","languages","variant"]','{"languages_removed":1,"languages_added":1}'),
  ('phb2-skill-retraining','Skill Retraining','194','characters','procedure',1,0,'Retraining can move up to 4 skill ranks from one skill to another class skill of one of the character''s classes, while still obeying normal rank limits.','["retraining","skills","variant"]','{"max_ranks_moved":4,"destination_must_be_class_skill":true,"rank_limits_apply":true}'),
  ('phb2-spell-power-retraining','Spell or Power Retraining','194','characters','procedure',1,0,'Retraining can exchange up to two known spells or psionic powers for other choices usable by the same class and of the same level as the choices replaced.','["retraining","spells","powers","variant"]','{"max_replacements":2,"same_class":true,"same_level":true}'),
  ('phb2-substitution-level-retraining','Substitution Level Retraining','194-195','characters','procedure',1,0,'A current class level can be traded for an eligible substitution level, or a substitution level can be exchanged for the normal class level, provided prerequisites are met now and would have been met when the level was originally taken.','["retraining","substitution-levels","variant"]','{"current_and_original_eligibility_required":true}'),
  ('phb2-retraining-costs','Optional Retraining Costs','194','characters','table',1,0,'The optional retraining-cost table assigns time and gp costs by retraining type; the subsystem also functions without these costs if the DM does not use them.','["retraining","cost","variant"]','{"class_feature":{"time":"1 week per 2 original class levels","gp_per_week":500},"feat":{"time":"2 weeks","gp":50},"skill":{"time":"1 week per 2 ranks changed","gp_per_week":25},"spell":{"time":"1 day","gp_per_spell_level":5},"substitution_level":{"time":"1 week per 2 original class levels","gp_per_week":500},"optional":true}'),
  ('phb2-rebuilding','Character Rebuilding','196','characters','subsystem',1,0,'Rebuilding is a broad character-revision system that can alter ability scores, class levels, race, templates, and related elements, normally only after completing a significant DM-designed rebuild quest.','["rebuilding","character-revision","quest","variant"]','{"quest_required":true,"scope":["ability scores","class levels","race","templates"]}'),
  ('phb2-ability-score-rebuilding','Ability Score Rebuilding','196-197','characters','procedure',1,0,'After a rebuild quest, ability scores can be reduced to generate points that are spent to raise other ability scores using the rebuilding tables; a score cannot be reduced below 8 or made illegal for another character option.','["rebuilding","ability-scores","variant"]','{"minimum_reduced_score":8,"cannot_invalidate_other_choices":true,"uses_point_tables":true}'),
  ('phb2-class-level-rebuilding','Class Level Rebuilding','197-198','characters','procedure',1,0,'After a rebuild quest, a character can replace a number of class levels equal to one-fifth of character level, rounded up, then recalculates attack/save progressions, hit points, skills, spells, and class features as directed.','["rebuilding","class-levels","variant"]','{"levels_replaceable":"ceil(character level / 5)"}'),
  ('phb2-race-rebuilding','Race Rebuilding','198-199','characters','procedure',1,0,'After a rebuild quest, a character can replace the original race with a new one, removing old racial traits and ability adjustments and applying the new race, then resolving feats, prestige classes, substitution levels, and level adjustment as necessary.','["rebuilding","race","variant"]','{"replace_racial_traits":true,"replace_racial_ability_modifiers":true,"known_languages_unchanged_without_language_retraining":true}'),
  ('phb2-rebuild-quests','Rebuild Quests','196,199-206','campaign','guidance',1,0,'Major rebuilding should be earned through a significant, challenging quest tied to the campaign; example quests are provided as models for DMs creating appropriate rebuild opportunities.','["rebuilding","quest","campaign","variant"]','{"recommended_rare":true,"dm_designed":true}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'phb2-3.5-rule-' || d.slug, 'phb2-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
